      "id": "git-github",
      "version": "60822.2"
    },
    {
      "id": "node",
      "version": "60823.1"
    },
    {
      "id": "spec-driven-product",
      "version": "60822.1"
    },
    {
      "id": "tidy-repo",
      "version": "60823.1"
    },
    {
      "id": "claudinite-growth",
      "version": "60823.2"
