1	#!/usr/bin/env node
2	// Perform every declared migration's write side in a checkout:
3	//   - file aliases  — "prefer Y, fall back to X, and rename X -> Y"
4	//   - materialize   — vendor pack templates into the repo's own tree
5	//   - rewrite       — repoint refs in place (idempotent literal replacements)
6	//   - declarePacks  — declare a pack (and its config) the member does not carry yet
7	//   - normalizeLocalDeclarations — rewrite local-pack declarations to `local/<id>`
8	// Idempotent: a no-op once everything has been applied. Dependency-free.
9	//
10	// Two roots. The DEST is the repo being healed (CLAUDE_PROJECT_DIR / cwd). The
11	// TEMPLATE source is the corpus that ships the migrations — the root this module
12	// sits two levels under (engine/migrations/): in the canon repo that's the repo
13	// root; in a consumer that mounts Claudinite at .claudinite/shared/, it's that
14	// mount root (so a template path like packs/…/stubs/foo.yml resolves against the
15	// mounted pack, while its dest lands in the consumer's own .github/). The two
16	// coincide in the canon repo.
17	//
18	// Runs against a local checkout (a session, CI, or a future SessionStart
19	// self-heal hook wired via bootstrap). Each member migrates ITSELF: the update flows
20	// runs this applier from the fresh canon clone it fetched, so even a dormant
21	// project catches up on every record ever landed — there is no fleet-wide
22	// apply pass and no retirement; the records simply accumulate.
23	import { existsSync, renameSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
24	import { dirname, join } from 'node:path';
25	import { fileURLToPath, pathToFileURL } from 'node:url';
26	import { loadMigrations, applyMigration } from './registry.mjs';
27	
28	export async function main() {
29	  const repoRoot = process.env.CLAUDE_PROJECT_DIR || process.cwd();
30	  const canonRoot = dirname(dirname(dirname(fileURLToPath(import.meta.url)))); // <corpus>/engine/migrations/
31	  const migrations = await loadMigrations();
32	
33	  const exists = (p) => existsSync(join(repoRoot, p));
34	  const read = (p) => (existsSync(join(repoRoot, p)) ? readFileSync(join(repoRoot, p), 'utf8') : null);
35	  const write = (p, c) => {
36	    mkdirSync(dirname(join(repoRoot, p)), { recursive: true });
37	    writeFileSync(join(repoRoot, p), c);
38	  };
39	  const move = (from, to) => {
40	    mkdirSync(dirname(join(repoRoot, to)), { recursive: true });
41	    renameSync(join(repoRoot, from), join(repoRoot, to));
42	  };
43	  const readTemplate = (p) => (existsSync(join(canonRoot, p)) ? readFileSync(join(canonRoot, p), 'utf8') : null);
44	
45	  const applied = [];
46	  for (const m of migrations) applied.push(...(await applyMigration(m, { exists, move, read, write, readTemplate })));
47	  if (applied.length) console.log(`Applied migrations:\n${applied.map((x) => `  ${x}`).join('\n')}`);
48	}
49	
50	const isMain = process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href;
51	if (isMain) {
52	  main().catch((e) => { console.error(`migrations apply failed: ${e.message}`); process.exit(1); });
53	}
54

